impl ContractAdvisory {
    pub fn code(&self) -> &'static str {
        match self {
            ContractAdvisory::DependsOnBoundary(_) => "OTA_CONTRACT_ADVISORY_DEPENDS_ON_BOUNDARY",
            ContractAdvisory::LikelyUnusedAttachment(_) => {
                "OTA_CONTRACT_ADVISORY_LIKELY_UNUSED_ATTACHMENT"
            }
            ContractAdvisory::IsolatedYarnReleaseShadow(_) => {
                "OTA_CONTRACT_ADVISORY_ISOLATED_YARN_RELEASE_SHADOW"
            }
            ContractAdvisory::MutatesManagedIsolatedPath(_) => {
                "OTA_CONTRACT_ADVISORY_TASK_MUTATES_MANAGED_ISOLATED_PATH"
            }
            ContractAdvisory::LegacyNodeRuntimeToolSplit(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_NODE_RUNTIME_TOOL_SPLIT"
            }
            ContractAdvisory::LegacyStandalonePoetry(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_STANDALONE_POETRY"
            }
            ContractAdvisory::LegacyToolchainProvider(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_TOOLCHAIN_PROVIDER"
            }
            ContractAdvisory::LegacyFlatToolchainFulfillment(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_FLAT_TOOLCHAIN_FULFILLMENT"
            }
            ContractAdvisory::LegacyHostServiceLifecycle(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_HOST_SERVICE_LIFECYCLE"
            }
            ContractAdvisory::LegacyServiceReadinessRun(_) => {
                "OTA_CONTRACT_ADVISORY_LEGACY_SERVICE_READINESS_RUN"
            }
            ContractAdvisory::ServiceUsesOpaqueShellStart(_) => {
                "OTA_CONTRACT_ADVISORY_SERVICE_OPAQUE_SHELL_START"
            }
            ContractAdvisory::ReplaceableFiniteShellCommand(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_FINITE_SHELL_COMMAND"
            }
            ContractAdvisory::ReplaceableDependencyHydrationOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_DEPENDENCY_HYDRATION"
            }
            ContractAdvisory::ExceptionalDependencyHydrationOverride(_) => {
                "OTA_CONTRACT_ADVISORY_EXCEPTIONAL_DEPENDENCY_HYDRATION_OVERRIDE"
            }
            ContractAdvisory::ReplaceableShellCheck(advisory) => match advisory.replacement_kind {
                ReplaceableShellCheckKind::File => {
                    "OTA_CONTRACT_ADVISORY_REPLACEABLE_SHELL_FILE_CHECK"
                }
                ReplaceableShellCheckKind::Env => {
                    "OTA_CONTRACT_ADVISORY_REPLACEABLE_SHELL_ENV_CHECK"
                }
            },
            ContractAdvisory::ReplaceableShellEnvMutation(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_SHELL_ENV_MUTATION"
            }
            ContractAdvisory::ReplaceableToolBootstrapOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_TOOL_BOOTSTRAP"
            }
            ContractAdvisory::ReplaceableSystemdServiceOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_SYSTEMD_SERVICE_OWNERSHIP"
            }
            ContractAdvisory::ReplaceableContainerNetworkOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_REPLACEABLE_CONTAINER_NETWORK_OWNERSHIP"
            }
            ContractAdvisory::ReplaceableAdapterInputOwnership(advisory) => {
                advisory.family.replaceable_ownership_code()
            }
            ContractAdvisory::NativePackageManagerLikelyWrongPlatform(_) => {
                "OTA_CONTRACT_ADVISORY_NATIVE_PACKAGE_MANAGER_LIKELY_WRONG_PLATFORM"
            }
            ContractAdvisory::MixedNativePackageOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_MIXED_NATIVE_PACKAGE_OWNERSHIP"
            }
            ContractAdvisory::EmptyAdapterInputMarker(advisory) => {
                advisory.family.empty_marker_code()
            }
            ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(_) => {
                "OTA_CONTRACT_ADVISORY_DUPLICATE_WORKFLOW_RENDERED_ENV_OWNERSHIP"
            }
            ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(advisory) => {
                advisory.field.code()
            }
            ContractAdvisory::SensitiveAgentWritablePath(_) => {
                "OTA_CONTRACT_ADVISORY_SENSITIVE_AGENT_WRITABLE_PATH"
            }
            ContractAdvisory::SensitiveWriteException(_) => {
                "OTA_CONTRACT_ADVISORY_SENSITIVE_WRITE_EXCEPTION"
            }
            ContractAdvisory::NonCanonicalExternalStateToken(_) => {
                "OTA_CONTRACT_ADVISORY_EXTERNAL_STATE_TOKEN_CANONICAL"
            }
            ContractAdvisory::AgentBootstrapUnpinned(_) => {
                "OTA_CONTRACT_ADVISORY_AGENT_BOOTSTRAP_UNPINNED"
            }
            ContractAdvisory::AgentSafeTaskNetwork(advisory) => match advisory.network_kind {
                TaskNetworkEffectKind::DependencyHydration => {
                    "OTA_CONTRACT_ADVISORY_AGENT_SAFE_TASK_DEPENDENCY_HYDRATION"
                }
                TaskNetworkEffectKind::ToolBootstrap => {
                    "OTA_CONTRACT_ADVISORY_AGENT_SAFE_TASK_TOOL_BOOTSTRAP"
                }
                TaskNetworkEffectKind::Broad => "OTA_CONTRACT_ADVISORY_AGENT_SAFE_TASK_NETWORK",
            },
            ContractAdvisory::AgentSafeTaskExternalState(_) => {
                "OTA_CONTRACT_ADVISORY_AGENT_SAFE_TASK_EXTERNAL_STATE"
            }
        }
    }

    pub(crate) const fn category(&self) -> &'static str {
        "contract"
    }

    pub(crate) const fn owner(&self) -> &'static str {
        "repo_contract"
    }

    pub fn summary(&self) -> String {
        match self {
            ContractAdvisory::DependsOnBoundary(advisory) => format!(
                "task `{}` depends_on `{}` across different execution boundaries",
                advisory.parent_task, advisory.dependency_task
            ),
            ContractAdvisory::LikelyUnusedAttachment(advisory) => format!(
                "context `{}` isolates `{}` but no task config points {} at `{}`",
                advisory.context_name,
                advisory.isolated_path,
                advisory.tool,
                advisory.effective_path
            ),
            ContractAdvisory::IsolatedYarnReleaseShadow(advisory) => {
                let declared_paths = advisory
                    .release_paths
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", ");
                format!(
                    "context `{}` isolates `{}` and shadows declared Yarn release path(s): {}",
                    advisory.context_name, advisory.isolated_path, declared_paths
                )
            }
            ContractAdvisory::MutatesManagedIsolatedPath(advisory) => format!(
                "task `{}` mutates managed isolated path `{}`",
                advisory.task_name, advisory.isolated_path
            ),
            ContractAdvisory::LegacyNodeRuntimeToolSplit(advisory) => format!(
                "Node contract uses split ownership (`runtimes.node` + tools: {}) instead of `toolchains.node`",
                advisory.package_managers.join(", ")
            ),
            ContractAdvisory::LegacyStandalonePoetry(advisory) => format!(
                "Poetry is modeled as a standalone tool instead of `toolchains.python.package_managers.poetry` ({})",
                advisory.locations.join(", ")
            ),
            ContractAdvisory::LegacyToolchainProvider(advisory) => format!(
                "toolchain `{}` keeps legacy provider ownership at `{}`",
                advisory.toolchain_name, advisory.location
            ),
            ContractAdvisory::LegacyFlatToolchainFulfillment(advisory) => format!(
                "toolchain `{}` keeps legacy flat fulfillment ownership at `{}`",
                advisory.toolchain_name, advisory.location
            ),
            ContractAdvisory::LegacyHostServiceLifecycle(advisory) => format!(
                "service `{}` keeps host lifecycle ownership on legacy top-level field(s) `{}`",
                advisory.service_name,
                advisory.locations.join("`, `")
            ),
            ContractAdvisory::LegacyServiceReadinessRun(advisory) => format!(
                "service `{}` keeps readiness ownership on legacy `run` at `{}`",
                advisory.service_name, advisory.location
            ),
            ContractAdvisory::ServiceUsesOpaqueShellStart(advisory) => format!(
                "task `{}` uses opaque shell `{}` for long-running service path `{}`",
                advisory.task_name, advisory.body_kind, advisory.body_location
            ),
            ContractAdvisory::ReplaceableFiniteShellCommand(advisory) => format!(
                "task `{}` uses replaceable shell `{}` instead of `command`",
                advisory.task_name, advisory.body_kind
            ),
            ContractAdvisory::ReplaceableDependencyHydrationOwnership(advisory) => format!(
                "task `{}` hard-codes dependency hydration in its task body",
                advisory.task_name
            ),
            ContractAdvisory::ExceptionalDependencyHydrationOverride(advisory) => format!(
                "task `{}` declares exceptional dependency hydration override `{}` for `{}`",
                advisory.task_name, advisory.flag, advisory.manager
            ),
            ContractAdvisory::ReplaceableShellCheck(advisory) => match advisory.replacement_kind {
                ReplaceableShellCheckKind::File => format!(
                    "check `{}` uses replaceable shell file glue for `{}`",
                    advisory.check_name, advisory.subject
                ),
                ReplaceableShellCheckKind::Env => format!(
                    "check `{}` uses replaceable shell env-file glue for `{}`",
                    advisory.check_name, advisory.subject
                ),
            },
            ContractAdvisory::ReplaceableShellEnvMutation(advisory) => format!(
                "task `{}` uses replaceable shell env-file mutation",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableToolBootstrapOwnership(advisory) => format!(
                "task `{}` hard-codes tool bootstrap in its task body",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableSystemdServiceOwnership(advisory) => format!(
                "task `{}` hard-codes systemd service ownership in its task body",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableContainerNetworkOwnership(advisory) => format!(
                "task `{}` hard-codes container network ownership in its task body",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableAdapterInputOwnership(advisory) => match advisory.family {
                AdapterInputFamily::Compose => format!(
                    "task `{}` hard-codes compose adapter input ownership in its task body",
                    advisory.task_name
                ),
                AdapterInputFamily::Bake => format!(
                    "task `{}` hard-codes Bake file selection in its task body",
                    advisory.task_name
                ),
                AdapterInputFamily::Helm => format!(
                    "task `{}` hard-codes Helm adapter ownership in its task body",
                    advisory.task_name
                ),
            },
            ContractAdvisory::NativePackageManagerLikelyWrongPlatform(advisory) => format!(
                "native prerequisite `{}` platform `{}` declares likely wrong-OS package manager `{}`",
                advisory.prerequisite_name, advisory.platform_name, advisory.manager_name
            ),
            ContractAdvisory::MixedNativePackageOwnership(advisory) => format!(
                "native prerequisite `{}` platform `{}` mixes manual install glue with manager-owned package truth",
                advisory.prerequisite_name, advisory.platform_name
            ),
            ContractAdvisory::EmptyAdapterInputMarker(advisory) => format!(
                "task `{}` declares empty {} adapter inputs",
                advisory.task_name,
                advisory.family.family_name()
            ),
            ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(advisory) => format!(
                "workflow `{}` profile `{}` duplicates rendered env artifact ownership in task `{}`",
                advisory.workflow_name, advisory.profile_name, advisory.task_name
            ),
            ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(advisory) => format!(
                "workflow `{}` duplicates {} `{}` ownership in task `{}`",
                advisory.workflow_name,
                advisory.field.family_name(),
                advisory.field.field_name(),
                advisory.task_name
            ),
            ContractAdvisory::SensitiveAgentWritablePath(advisory) => format!(
                "`agent.writable_paths` includes sensitive {} `{}`",
                advisory.category, advisory.path
            ),
            ContractAdvisory::SensitiveWriteException(advisory) => format!(
                "`agent.exceptions.sensitive_writes` includes unnecessary path `{}`",
                advisory.path
            ),
            ContractAdvisory::NonCanonicalExternalStateToken(advisory) => format!(
                "task `{}` uses non-canonical external-state token `{}`",
                advisory.task_name, advisory.token
            ),
            ContractAdvisory::AgentBootstrapUnpinned(advisory) => {
                format!("`{}` should pin the ota release version", advisory.field)
            }
            ContractAdvisory::AgentSafeTaskNetwork(advisory) => {
                format!("{}", agent_safe_network_summary(advisory))
            }
            ContractAdvisory::AgentSafeTaskExternalState(advisory) => format!(
                "agent-safe task `{}` mutates external state: {}",
                advisory.task_name,
                advisory.systems.join(", ")
            ),
        }
    }

    pub fn why(&self) -> String {
        match self {
            ContractAdvisory::DependsOnBoundary(advisory) => format!(
                "execution differs across the dependency edge ({}) so only durable external side effects survive; in-process, session-local, and container-local prep does not carry across",
                describe_boundary_differences(&advisory.parent, &advisory.dependency).join(", ")
            ),
            ContractAdvisory::LikelyUnusedAttachment(advisory) => format!(
                "the attached path is durable, but `{}` only benefits if tasks in context `{}` point {} at `{}`",
                advisory.isolated_path,
                advisory.context_name,
                advisory.tool,
                advisory.effective_path
            ),
            ContractAdvisory::IsolatedYarnReleaseShadow(advisory) => format!(
                "task(s) {} run Yarn in context `{}`, and mounting `{}` as an isolated path can hide committed `.yarn/releases/yarn-*.cjs` artifacts from `/workspace`, causing late container-mode install/verify failures",
                advisory
                    .task_names
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
                advisory.context_name,
                advisory.isolated_path
            ),
            ContractAdvisory::MutatesManagedIsolatedPath(advisory) => format!(
                "task `{}` appears to mutate `{}`, which is declared under `execution.contexts.{}.attachments.isolated_paths`",
                advisory.task_name, advisory.isolated_path, advisory.context_name
            ),
            ContractAdvisory::LegacyNodeRuntimeToolSplit(advisory) => format!(
                "split Node ownership keeps package-manager activation/tool ownership detached from runtime ownership; this increases onboarding drift and makes missing-tool remediation less deterministic than a `toolchains.node` contract (current runtime: `{}`)",
                advisory.runtime_version
            ),
            ContractAdvisory::LegacyStandalonePoetry(_) => String::from(
                "Poetry owns Python dependency installation, lockfile semantics, virtualenv behavior, and often task execution through `poetry run`; keeping it as a standalone tool splits Python ecosystem ownership away from `toolchains.python`",
            ),
            ContractAdvisory::LegacyToolchainProvider(advisory) => format!(
                "toolchain `{}` still depends on legacy `provider` compatibility at `{}` (`{}`) instead of keeping fulfillment ownership under the canonical structured `fulfillment` surface",
                advisory.toolchain_name,
                advisory.location,
                toolchain_provider_label(advisory.provider)
            ),
            ContractAdvisory::LegacyFlatToolchainFulfillment(advisory) => format!(
                "toolchain `{}` still depends on legacy flat fulfillment compatibility at `{}` (`{}`) instead of the canonical structured `fulfillment.mode` / `fulfillment.source` surface",
                advisory.toolchain_name,
                advisory.location,
                match advisory.mode {
                    ToolchainFulfillmentMode::None => "none",
                    ToolchainFulfillmentMode::Run => "run",
                }
            ),
            ContractAdvisory::LegacyHostServiceLifecycle(advisory) => format!(
                "service `{}` keeps host lifecycle truth on legacy top-level field(s) `{}` instead of an explicit `manager.kind: host` owner, which leaves host service ownership less standardized than the canonical lifecycle surface",
                advisory.service_name,
                advisory.locations.join("`, `")
            ),
            ContractAdvisory::LegacyServiceReadinessRun(advisory) => format!(
                "service `{}` keeps readiness truth on legacy shell `run` at `{}` instead of a structured `kind` contract or named `probe`, which keeps service-readiness ownership less governable and less portable than the canonical surfaces",
                advisory.service_name, advisory.location
            ),
            ContractAdvisory::ServiceUsesOpaqueShellStart(advisory) => format!(
                "task `{}` declares `runtime.kind: service` at `{}`, but starts that long-running workload through opaque shell `{}` at `{}`; this hides launch semantics from Ota and weakens governance around startup, interruption, and service ownership compared with `launch.kind: command`",
                advisory.task_name,
                advisory.runtime_location,
                advisory.body_kind,
                advisory.body_location
            ),
            ContractAdvisory::ReplaceableFiniteShellCommand(advisory) => format!(
                "task `{}` keeps a finite argv-shaped command in shell `{}` at `{}` (`{}`), which is less governable and less inspectable than the first-class `command` surface",
                advisory.task_name,
                advisory.body_kind,
                advisory.body_location,
                advisory.command_preview
            ),
            ContractAdvisory::ReplaceableDependencyHydrationOwnership(advisory) => format!(
                "task `{}` hard-codes a dependency-hydration shell (`{}`), which hides setup ownership from Ota instead of declaring it under `prepare.kind: dependency_hydration`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ExceptionalDependencyHydrationOverride(advisory) => format!(
                "task `{}` declares `{}` on structured {} hydration; that weakens normal package-manager safety and should only be kept when the repo truth genuinely requires the override",
                advisory.task_name, advisory.flag, advisory.manager
            ),
            ContractAdvisory::ReplaceableShellCheck(advisory) => match advisory.replacement_kind {
                ReplaceableShellCheckKind::File => format!(
                    "check `{}` uses an obvious shell file-state command (`{}`), which is less portable and less governable than a first-class `kind: file` check",
                    advisory.check_name, advisory.command
                ),
                ReplaceableShellCheckKind::Env => format!(
                    "check `{}` uses an obvious shell env-file assertion (`{}`), which is less portable and less governable than a first-class `kind: env` check",
                    advisory.check_name, advisory.command
                ),
            },
            ContractAdvisory::ReplaceableShellEnvMutation(advisory) => format!(
                "task `{}` rewrites one env file through shell mutation (`{}`), which is less portable and less governable than `action.kind: ensure_env_file` with deterministic `mode: replace` keys",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableToolBootstrapOwnership(advisory) => format!(
                "task `{}` hard-codes tool bootstrap shell (`{}`), which hides contract-owned tool installation from Ota instead of declaring it under `prepare.kind: tool_bootstrap`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableSystemdServiceOwnership(advisory) => format!(
                "task `{}` hard-codes systemd service lifecycle or readiness shell (`{}`), which hides host service ownership from Ota instead of declaring it under `services.<name>.manager.kind: host`, `manager.host.kind: systemd`, and `readiness.kind: systemd_active`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableContainerNetworkOwnership(advisory) => format!(
                "task `{}` hard-codes container network bootstrap inside its task body (`{}`), which hides Docker network ownership from Ota instead of declaring it under `action.kind: ensure_container_network`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableAdapterInputOwnership(advisory) => {
                replaceable_adapter_ownership_why(advisory)
            }
            ContractAdvisory::NativePackageManagerLikelyWrongPlatform(advisory) => format!(
                "`{}` declares package manager `{}` under platform `{}`, which is likely the wrong host package lane for that OS and weakens fulfillment and policy truth",
                advisory.location, advisory.manager_name, advisory.platform_name
            ),
            ContractAdvisory::MixedNativePackageOwnership(advisory) => format!(
                "`{}` combines opaque manual install glue with manager-scoped package lanes ({}) on the same platform entry; that splits native prerequisite ownership between shell instructions and Ota-owned package fulfillment",
                advisory.location,
                advisory.package_managers.join(", ")
            ),
            ContractAdvisory::EmptyAdapterInputMarker(advisory) => format!(
                "`{}` is present but empty, so it does not declare any {} adapter input ownership; keep adapter-input surfaces only when they own concrete truth such as adapter cwd, env files, compose files, profiles, or project naming",
                advisory.location,
                advisory.family.family_name()
            ),
            ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(advisory) => format!(
                "workflow `{}` profile `{}` renders `{}`, but task `{}` also declares that same file under `{}`; Ota already projects rendered workflow env artifacts into the selected workflow task closure, so the duplicate task ownership is drift-prone",
                advisory.workflow_name,
                advisory.profile_name,
                advisory.path,
                advisory.task_name,
                advisory.location
            ),
            ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(advisory) => format!(
                "workflow `{}` owns {} `{}` at `{}`, but task `{}` also declares its own value under `{}`; selected-path adapter ownership should stay in one declarative place",
                advisory.workflow_name,
                advisory.field.family_name(),
                advisory.field_value,
                advisory.workflow_location,
                advisory.task_name,
                advisory.location
            ),
            ContractAdvisory::SensitiveAgentWritablePath(advisory) => advisory.reason.clone(),
            ContractAdvisory::SensitiveWriteException(advisory) => advisory.reason.clone(),
            ContractAdvisory::NonCanonicalExternalStateToken(advisory) => format!(
                "`effects.external_state` participates in policy, doctor, and agent-safety governance; `{}` is a repo-local alias for the shipped canonical token `{}`, so keeping the canonical token improves cross-repo policy reuse and makes side-effect review more consistent (shipped examples: {})",
                advisory.token,
                advisory.canonical_token,
                shipped_external_state_token_examples()
            ),
            ContractAdvisory::AgentBootstrapUnpinned(advisory) => format!(
                "`{}` installs ota from a moving target without an explicit version pin",
                advisory.field
            ),
            ContractAdvisory::AgentSafeTaskNetwork(advisory) => {
                format!("{}", agent_safe_network_why(advisory))
            }
            ContractAdvisory::AgentSafeTaskExternalState(advisory) => format!(
                "task `{}` is declared agent-safe but mutates out-of-repo state (`{}`), so repo write boundaries alone do not bound its blast radius",
                advisory.task_name,
                advisory.systems.join(", ")
            ),
        }
    }

    pub fn impact(&self) -> Option<String> {
        match self {
            ContractAdvisory::DependsOnBoundary(_) => Some(String::from(
                "only durable external side effects carry across",
            )),
            ContractAdvisory::LikelyUnusedAttachment(_)
            | ContractAdvisory::IsolatedYarnReleaseShadow(_)
            | ContractAdvisory::MutatesManagedIsolatedPath(_)
            | ContractAdvisory::LegacyNodeRuntimeToolSplit(_)
            | ContractAdvisory::LegacyStandalonePoetry(_)
            | ContractAdvisory::LegacyToolchainProvider(_)
            | ContractAdvisory::LegacyFlatToolchainFulfillment(_)
            | ContractAdvisory::LegacyHostServiceLifecycle(_)
            | ContractAdvisory::LegacyServiceReadinessRun(_)
            | ContractAdvisory::ServiceUsesOpaqueShellStart(_)
            | ContractAdvisory::ReplaceableFiniteShellCommand(_)
            | ContractAdvisory::ReplaceableDependencyHydrationOwnership(_)
            | ContractAdvisory::ExceptionalDependencyHydrationOverride(_)
            | ContractAdvisory::ReplaceableShellCheck(_)
            | ContractAdvisory::ReplaceableShellEnvMutation(_)
            | ContractAdvisory::ReplaceableToolBootstrapOwnership(_)
            | ContractAdvisory::ReplaceableSystemdServiceOwnership(_)
            | ContractAdvisory::ReplaceableContainerNetworkOwnership(_)
            | ContractAdvisory::ReplaceableAdapterInputOwnership(_)
            | ContractAdvisory::NativePackageManagerLikelyWrongPlatform(_)
            | ContractAdvisory::MixedNativePackageOwnership(_)
            | ContractAdvisory::EmptyAdapterInputMarker(_)
            | ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(_)
            | ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(_)
            | ContractAdvisory::SensitiveAgentWritablePath(_)
            | ContractAdvisory::SensitiveWriteException(_)
            | ContractAdvisory::NonCanonicalExternalStateToken(_)
            | ContractAdvisory::AgentBootstrapUnpinned(_)
            | ContractAdvisory::AgentSafeTaskNetwork(_)
            | ContractAdvisory::AgentSafeTaskExternalState(_) => None,
        }
    }

    pub fn drift(&self) -> Option<String> {
        match self {
            ContractAdvisory::DependsOnBoundary(advisory) => Some(
                describe_boundary_differences(&advisory.parent, &advisory.dependency).join(", "),
            ),
            ContractAdvisory::LikelyUnusedAttachment(_)
            | ContractAdvisory::IsolatedYarnReleaseShadow(_)
            | ContractAdvisory::MutatesManagedIsolatedPath(_)
            | ContractAdvisory::LegacyNodeRuntimeToolSplit(_)
            | ContractAdvisory::LegacyStandalonePoetry(_)
            | ContractAdvisory::LegacyToolchainProvider(_)
            | ContractAdvisory::LegacyFlatToolchainFulfillment(_)
            | ContractAdvisory::LegacyHostServiceLifecycle(_)
            | ContractAdvisory::LegacyServiceReadinessRun(_)
            | ContractAdvisory::ServiceUsesOpaqueShellStart(_)
            | ContractAdvisory::ReplaceableFiniteShellCommand(_)
            | ContractAdvisory::ReplaceableDependencyHydrationOwnership(_)
            | ContractAdvisory::ExceptionalDependencyHydrationOverride(_)
            | ContractAdvisory::ReplaceableShellCheck(_)
            | ContractAdvisory::ReplaceableShellEnvMutation(_)
            | ContractAdvisory::ReplaceableToolBootstrapOwnership(_)
            | ContractAdvisory::ReplaceableSystemdServiceOwnership(_)
            | ContractAdvisory::ReplaceableContainerNetworkOwnership(_)
            | ContractAdvisory::ReplaceableAdapterInputOwnership(_)
            | ContractAdvisory::NativePackageManagerLikelyWrongPlatform(_)
            | ContractAdvisory::MixedNativePackageOwnership(_)
            | ContractAdvisory::EmptyAdapterInputMarker(_)
            | ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(_)
            | ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(_)
            | ContractAdvisory::SensitiveAgentWritablePath(_)
            | ContractAdvisory::SensitiveWriteException(_)
            | ContractAdvisory::NonCanonicalExternalStateToken(_)
            | ContractAdvisory::AgentBootstrapUnpinned(_)
            | ContractAdvisory::AgentSafeTaskNetwork(_)
            | ContractAdvisory::AgentSafeTaskExternalState(_) => None,
        }
    }

    pub fn fix(&self) -> Option<String> {
        match self {
            ContractAdvisory::DependsOnBoundary(_) => None,
            ContractAdvisory::LikelyUnusedAttachment(advisory) => Some(format!(
                "point {} at `{}`",
                advisory.tool, advisory.effective_path
            )),
            ContractAdvisory::IsolatedYarnReleaseShadow(_) => None,
            ContractAdvisory::MutatesManagedIsolatedPath(_)
            | ContractAdvisory::LegacyNodeRuntimeToolSplit(_)
            | ContractAdvisory::LegacyStandalonePoetry(_)
            | ContractAdvisory::LegacyToolchainProvider(_)
            | ContractAdvisory::LegacyFlatToolchainFulfillment(_)
            | ContractAdvisory::LegacyHostServiceLifecycle(_)
            | ContractAdvisory::LegacyServiceReadinessRun(_)
            | ContractAdvisory::ServiceUsesOpaqueShellStart(_)
            | ContractAdvisory::ReplaceableFiniteShellCommand(_)
            | ContractAdvisory::ReplaceableDependencyHydrationOwnership(_)
            | ContractAdvisory::ExceptionalDependencyHydrationOverride(_)
            | ContractAdvisory::ReplaceableShellCheck(_)
            | ContractAdvisory::ReplaceableShellEnvMutation(_)
            | ContractAdvisory::ReplaceableToolBootstrapOwnership(_)
            | ContractAdvisory::ReplaceableSystemdServiceOwnership(_)
            | ContractAdvisory::ReplaceableContainerNetworkOwnership(_)
            | ContractAdvisory::ReplaceableAdapterInputOwnership(_)
            | ContractAdvisory::NativePackageManagerLikelyWrongPlatform(_)
            | ContractAdvisory::MixedNativePackageOwnership(_)
            | ContractAdvisory::EmptyAdapterInputMarker(_)
            | ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(_)
            | ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(_)
            | ContractAdvisory::SensitiveAgentWritablePath(_)
            | ContractAdvisory::SensitiveWriteException(_)
            | ContractAdvisory::NonCanonicalExternalStateToken(_)
            | ContractAdvisory::AgentBootstrapUnpinned(_)
            | ContractAdvisory::AgentSafeTaskNetwork(_)
            | ContractAdvisory::AgentSafeTaskExternalState(_) => None,
        }
    }

    pub fn next(&self) -> String {
        match self {
            ContractAdvisory::DependsOnBoundary(advisory) => format!(
                "keep `{}` and `{}` on the same execution boundary when the dependency is meant to prepare the parent in place, or make the durable shared surface explicit",
                advisory.parent_task, advisory.dependency_task
            ),
            ContractAdvisory::LikelyUnusedAttachment(advisory) => format!(
                "configure {} to use `{}` or remove `execution.contexts.{}.attachments.isolated_paths: [{}]` if that cache should stay container-local",
                advisory.tool,
                advisory.effective_path,
                advisory.context_name,
                advisory.isolated_path
            ),
            ContractAdvisory::IsolatedYarnReleaseShadow(advisory) => format!(
                "remove `{}` from `execution.contexts.{}.attachments.isolated_paths`, or narrow isolation to cache-only paths (for example `.yarn/cache`) so committed `.yarn/releases/*` stays visible to Yarn tasks in this container context",
                advisory.isolated_path, advisory.context_name
            ),
            ContractAdvisory::MutatesManagedIsolatedPath(advisory) => format!(
                "remove manual cleanup of `{}` from task `{}` and let the tool manage that isolated attachment inside context `{}`",
                advisory.isolated_path, advisory.task_name, advisory.context_name
            ),
            ContractAdvisory::LegacyNodeRuntimeToolSplit(advisory) => format!(
                "migrate to `toolchains.node` ownership: remove `runtimes.node`, add `toolchains.node.version: {}`, and move {} under `toolchains.node.package_managers`",
                advisory.runtime_version,
                advisory
                    .package_managers
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            ContractAdvisory::LegacyStandalonePoetry(_) => String::from(
                "add or widen `toolchains.python`, move Poetry version governance under `toolchains.python.package_managers.poetry`, and remove the standalone Poetry declaration from the listed location(s)",
            ),
            ContractAdvisory::LegacyToolchainProvider(advisory) => format!(
                "remove `{}` and keep toolchain `{}` on structured `fulfillment`; canonical shipped toolchain ownership already implies provider `{}`",
                advisory.location,
                advisory.toolchain_name,
                toolchain_provider_label(advisory.provider)
            ),
            ContractAdvisory::LegacyFlatToolchainFulfillment(advisory) => format!(
                "replace `{}` with structured `fulfillment: {{ mode: {} }}` and add `source` only when this repo truthfully needs a non-default fulfillment source such as `mise`",
                advisory.location,
                match advisory.mode {
                    ToolchainFulfillmentMode::None => "none",
                    ToolchainFulfillmentMode::Run => "run",
                }
            ),
            ContractAdvisory::LegacyHostServiceLifecycle(advisory) => format!(
                "move service `{}` host lifecycle truth under `services.{}.manager.kind: host`, then relocate `{}` to `manager.start` / `manager.stop` so Ota owns host service lifecycle through one canonical surface",
                advisory.service_name,
                advisory.service_name,
                advisory.locations.join("`, `")
            ),
            ContractAdvisory::LegacyServiceReadinessRun(advisory) => format!(
                "replace `{}` with structured service readiness under `services.{}.readiness.kind` (or a named `readiness.probe`) so Ota owns readiness through one canonical surface instead of shell `run` glue",
                advisory.location, advisory.service_name
            ),
            ContractAdvisory::ServiceUsesOpaqueShellStart(advisory) => format!(
                "replace `{}` with `{}` modeled as `kind: command`; keep service exposure and readiness under `{}` and reserve `run`/`script` for shell-oriented finite tasks",
                advisory.body_location, advisory.launch_location, advisory.runtime_location
            ),
            ContractAdvisory::ReplaceableFiniteShellCommand(advisory) => format!(
                "replace `{}` with `tasks.{}.command` using `exe: {}` and `args: [{}]`; reserve `run`/`script` for shell behavior that cannot be modeled structurally",
                advisory.body_location,
                advisory.task_name,
                advisory.suggested_exe,
                advisory
                    .suggested_args
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            ContractAdvisory::ReplaceableDependencyHydrationOwnership(advisory) => format!(
                "move dependency hydration out of task `{}` shell: declare `prepare.kind: dependency_hydration` with a typed source instead of `{}`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ExceptionalDependencyHydrationOverride(advisory) => format!(
                "keep `{}` on {} hydration only when the repo truth genuinely requires it; otherwise remove the override and return task `{}` to normal package-manager hydration semantics",
                advisory.flag, advisory.manager, advisory.task_name
            ),
            ContractAdvisory::ReplaceableShellCheck(advisory) => match advisory.replacement_kind {
                ReplaceableShellCheckKind::File => file_check_replacement_guidance(
                    advisory.check_name.as_str(),
                    advisory.subject.as_str(),
                ),
                ReplaceableShellCheckKind::Env => format!(
                    "replace check `{}` with `kind: env` for `{}` instead of shell `run` glue",
                    advisory.check_name, advisory.subject
                ),
            },
            ContractAdvisory::ReplaceableShellEnvMutation(advisory) => format!(
                "replace shell env-file mutation in task `{}` with `action.kind: ensure_env_file` (or `ensure_bundle`) and explicit `mode: replace` keys",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableToolBootstrapOwnership(advisory) => format!(
                "move tool bootstrap out of task `{}` shell: declare `prepare.kind: tool_bootstrap` with an explicit typed source instead of `{}`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableSystemdServiceOwnership(advisory) => format!(
                "move systemd service ownership out of task `{}` body: declare `services.<name>.manager.kind: host`, `manager.host.kind: systemd`, and `readiness.kind: systemd_active` instead of shelling `{}`",
                advisory.task_name, advisory.command
            ),
            ContractAdvisory::ReplaceableContainerNetworkOwnership(advisory) => format!(
                "move container network ownership out of task `{}` body: use `action.kind: ensure_container_network` so Ota owns Docker network bootstrap declaratively",
                advisory.task_name
            ),
            ContractAdvisory::ReplaceableAdapterInputOwnership(advisory) => {
                replaceable_adapter_ownership_next(advisory)
            }
            ContractAdvisory::NativePackageManagerLikelyWrongPlatform(advisory) => format!(
                "move `{}` to a package manager lane that matches platform `{}` and keep host package truth OS-specific",
                advisory.location, advisory.platform_name
            ),
            ContractAdvisory::MixedNativePackageOwnership(advisory) => format!(
                "keep manager-owned package installs under `{}` and move opaque package-oriented shell glue out of `{}`; if the manual step is still needed, separate it so Ota-owned package fulfillment stays clear",
                advisory.package_managers.join(", "),
                advisory.location
            ),
            ContractAdvisory::EmptyAdapterInputMarker(advisory) => format!(
                "remove `{}` if the task does not own concrete {} adapter input truth, or declare the real fields under it instead of keeping an empty marker",
                advisory.location,
                advisory.family.family_name()
            ),
            ContractAdvisory::DuplicateWorkflowRenderedEnvOwnership(advisory) => format!(
                "remove `{}` from task `{}`; workflow `{}` profile `{}` already renders `{}` and Ota injects that artifact into the selected workflow task closure automatically",
                advisory.location,
                advisory.task_name,
                advisory.workflow_name,
                advisory.profile_name,
                advisory.path
            ),
            ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(advisory) => format!(
                "remove `{}` from task `{}` or keep workflow-owned {} `{}` on `{}`; selected-path adapter ownership should stay on one shared workflow adapter overlay or one task-local declarative surface",
                advisory.location,
                advisory.task_name,
                advisory.field.family_name(),
                advisory.field.field_name(),
                advisory.workflow_location
            ),
            ContractAdvisory::SensitiveAgentWritablePath(advisory) => {
                format!("{}", sensitive_agent_writable_path_next(advisory))
            }
            ContractAdvisory::SensitiveWriteException(advisory) => format!(
                "remove `{}` from `agent.exceptions.sensitive_writes`, or move it to `agent.protected_paths` / tighten `agent.writable_paths` if this path should stay guarded",
                advisory.path
            ),
            ContractAdvisory::NonCanonicalExternalStateToken(advisory) => format!(
                "replace `effects.external_state: [{}]` with canonical token `{}` unless this task truly mutates a distinct external system not covered by the shipped vocabulary",
                advisory.token, advisory.canonical_token
            ),
            ContractAdvisory::AgentBootstrapUnpinned(advisory) => format!(
                "set `{}` to an explicit ota install pin, for example by pinning `OTA_VERSION=vX.Y.Z` (or a `--version`/`-Version` flag), or by using `OTA_GIT_REV=<exact-commit>` for unreleased source pressure tests, to keep agent bootstrap deterministic",
                advisory.field
            ),
            ContractAdvisory::AgentSafeTaskNetwork(advisory) => {
                format!("{}", agent_safe_network_next(advisory))
            }
            ContractAdvisory::AgentSafeTaskExternalState(advisory) => format!(
                "keep `effects.external_state` explicit for `{}`, and remove the task from `agent.safe_tasks` or `safe_for_agent: true` when unattended mutation of `{}` is not acceptable",
                advisory.task_name,
                advisory.systems.join(", ")
            ),
        }
    }
}

fn agent_safe_network_summary(advisory: &AgentSafeTaskNetworkAdvisory) -> String {
    match advisory.network_kind {
        TaskNetworkEffectKind::DependencyHydration => format!(
            "agent-safe task `{}` performs network dependency hydration",
            advisory.task_name
        ),
        TaskNetworkEffectKind::ToolBootstrap => format!(
            "agent-safe task `{}` performs network tool bootstrap",
            advisory.task_name
        ),
        TaskNetworkEffectKind::Broad => format!(
            "agent-safe task `{}` requires network access",
            advisory.task_name
        ),
    }
}

fn agent_safe_network_why(advisory: &AgentSafeTaskNetworkAdvisory) -> String {
    match advisory.network_kind {
        TaskNetworkEffectKind::DependencyHydration => format!(
            "task `{}` is declared agent-safe and performs dependency hydration over the network (for example lockfile-backed package-manager fetches); this is narrower than arbitrary remote mutation but still depends on registry/service reachability outside repo write boundaries",
            advisory.task_name
        ),
        TaskNetworkEffectKind::ToolBootstrap => format!(
            "task `{}` is declared agent-safe and bootstraps required tooling over the network (for example installing `uv` through `pip`) before execution; this is narrower than arbitrary remote mutation but still depends on package index reachability and mutable tool-install state outside repo write boundaries",
            advisory.task_name
        ),
        TaskNetworkEffectKind::Broad => format!(
            "task `{}` is declared agent-safe but also declares `effects.network: true`, so unattended execution still depends on registry, API, or remote service reachability",
            advisory.task_name
        ),
    }
}

fn agent_safe_network_next(advisory: &AgentSafeTaskNetworkAdvisory) -> String {
    match advisory.network_kind {
        TaskNetworkEffectKind::DependencyHydration => format!(
            "keep `effects.network: true` with `effects.network_kind: dependency_hydration` explicit for `{}`, and keep lockfile/provenance discipline strict on this task path",
            advisory.task_name
        ),
        TaskNetworkEffectKind::ToolBootstrap => format!(
            "keep `effects.network: true` with `effects.network_kind: tool_bootstrap` explicit for `{}`, and remove the task from `agent.safe_tasks` or `safe_for_agent: true` when unattended tool installation is not acceptable",
            advisory.task_name
        ),
        TaskNetworkEffectKind::Broad => format!(
            "keep `effects.network: true` explicit for `{}`, and remove the task from `agent.safe_tasks` or `safe_for_agent: true` when unattended networked execution is not acceptable",
            advisory.task_name
        ),
    }
}

fn sensitive_agent_writable_path_next(advisory: &SensitiveAgentWritablePathAdvisory) -> String {
    match advisory.category.as_str() {
        "repo-contract" => format!(
            "move `{}` from `agent.writable_paths` to `agent.protected_paths`, or set `agent.posture: contract_authoring` if this slice intentionally authors repo contracts",
            advisory.path
        ),
        "ci-topology" | "runtime-topology" => format!(
            "move `{}` from `agent.writable_paths` to `agent.protected_paths`, or set `agent.posture: infra_authoring` if this slice intentionally authors CI or runtime topology",
            advisory.path
        ),
        _ => format!(
            "move `{}` from `agent.writable_paths` to `agent.protected_paths` unless this slice intentionally needs this narrow exception; use `agent.exceptions.sensitive_writes` only when the broader posture is still correct",
            advisory.path
        ),
    }
}

pub fn collect_contract_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    collect_contract_advisories_with_contract_path(contract, None)
}

pub fn collect_contract_advisories_with_contract_path(
    contract: &Contract,
    contract_path: Option<&Path>,
) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    advisories.extend(collect_depends_on_boundary_advisories(contract));
    advisories.extend(collect_attachment_use_advisories(contract));
    advisories.extend(
        collect_isolated_yarn_release_shadow_advisories_with_contract_path(contract, contract_path),
    );
    advisories.extend(collect_managed_isolated_path_mutation_advisories(contract));
    advisories.extend(collect_legacy_node_runtime_tool_split_advisories(contract));
    advisories.extend(collect_legacy_standalone_poetry_advisories(contract));
    advisories.extend(collect_legacy_toolchain_provider_advisories(contract));
    advisories.extend(collect_legacy_flat_toolchain_fulfillment_advisories(
        contract,
    ));
    advisories.extend(collect_legacy_host_service_lifecycle_advisories(contract));
    advisories.extend(collect_legacy_service_readiness_run_advisories(contract));
    advisories.extend(collect_service_uses_opaque_shell_start_advisories(contract));
    advisories.extend(collect_replaceable_finite_shell_command_advisories(
        contract,
    ));
    advisories.extend(collect_replaceable_dependency_hydration_ownership_advisories(contract));
    advisories.extend(collect_exceptional_dependency_hydration_override_advisories(contract));
    advisories.extend(collect_replaceable_shell_check_advisories(contract));
    advisories.extend(collect_replaceable_shell_env_mutation_advisories(contract));
    advisories.extend(collect_replaceable_tool_bootstrap_ownership_advisories(
        contract,
    ));
    advisories.extend(collect_replaceable_systemd_service_ownership_advisories(
        contract,
    ));
    advisories.extend(collect_replaceable_container_network_ownership_advisories(
        contract,
    ));
    advisories.extend(collect_replaceable_compose_env_file_ownership_advisories(
        contract,
    ));
    advisories.extend(collect_replaceable_bake_file_ownership_advisories(contract));
    advisories.extend(collect_native_package_manager_platform_advisories(contract));
    advisories.extend(collect_mixed_native_package_ownership_advisories(contract));
    advisories.extend(collect_empty_adapter_input_marker_advisories(contract));
    advisories.extend(collect_duplicate_workflow_rendered_env_ownership_advisories(contract));
    advisories.extend(collect_duplicate_workflow_adapter_input_ownership_advisories(contract));
    advisories.extend(collect_sensitive_agent_writable_path_advisories(contract));
    advisories.extend(collect_sensitive_write_exception_advisories(contract));
    advisories.extend(collect_non_canonical_external_state_token_advisories(
        contract,
    ));
    advisories.extend(collect_agent_bootstrap_unpinned_advisories(contract));
    advisories.extend(collect_agent_safe_task_effect_advisories(contract));
    advisories
}

fn collect_legacy_node_runtime_tool_split_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    if contract.toolchains.contains_key("node") {
        return Vec::new();
    }
    let Some(runtime_requirement) = contract.runtimes.get("node") else {
        return Vec::new();
    };

    let mut package_managers = Vec::new();
    for name in ["pnpm", "yarn"] {
        let Some(requirement) = contract.tools.get(name) else {
            continue;
        };
        if requirement.acquisition().is_some_and(|acquisition| {
            acquisition.provider == crate::schema::ToolAcquisitionProvider::Corepack
        }) {
            continue;
        }
        package_managers.push(String::from(name));
    }

    if package_managers.is_empty() {
        return Vec::new();
    }

    vec![ContractAdvisory::LegacyNodeRuntimeToolSplit(
        LegacyNodeRuntimeToolSplitAdvisory {
            runtime_version: runtime_requirement.version().to_string(),
            package_managers,
        },
    )]
}

fn collect_legacy_standalone_poetry_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    if contract
        .toolchains
        .iter()
        .any(|(toolchain_name, toolchain)| {
            declared_toolchain_contract(toolchain_name, toolchain)
                .is_some_and(|provider| provider.owned_runtime() == "python")
                && (toolchain.package_managers.contains_key("poetry")
                    || toolchain
                        .platforms
                        .values()
                        .any(|platform| platform.package_managers.contains_key("poetry")))
        })
    {
        return Vec::new();
    }

    let mut locations = Vec::new();
    if contract.tools.contains_key("poetry") {
        locations.push(String::from("tools.poetry"));
    }
    if let Some(execution) = contract.execution.as_ref() {
        for (context_name, context) in &execution.contexts {
            if context.requirements.tools.contains_key("poetry") {
                locations.push(format!(
                    "execution.contexts.{context_name}.requirements.tools.poetry"
                ));
            }
        }
    }
    for (task_name, task) in &contract.tasks {
        if task.requirements.tools.contains_key("poetry") {
            locations.push(format!("tasks.{task_name}.requirements.tools.poetry"));
        }
        for (index, branch) in task.requirements.any_of.iter().enumerate() {
            if branch.tools.contains_key("poetry") {
                locations.push(format!(
                    "tasks.{task_name}.requirements.any_of[{index}].tools.poetry"
                ));
            }
        }
    }

    if locations.is_empty() {
        return Vec::new();
    }

    vec![ContractAdvisory::LegacyStandalonePoetry(
        LegacyStandalonePoetryAdvisory { locations },
    )]
}

fn collect_legacy_toolchain_provider_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for (toolchain_name, toolchain) in &contract.toolchains {
        let Some(provider) = toolchain.provider else {
            continue;
        };
        if declared_toolchain_contract(toolchain_name, toolchain).is_none() {
            continue;
        }
        advisories.push(ContractAdvisory::LegacyToolchainProvider(
            LegacyToolchainProviderAdvisory {
                toolchain_name: toolchain_name.clone(),
                provider,
                location: format!("toolchains.{toolchain_name}.provider"),
            },
        ));
    }
    advisories
}

fn collect_legacy_flat_toolchain_fulfillment_advisories(
    contract: &Contract,
) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for (toolchain_name, toolchain) in &contract.toolchains {
        if !toolchain.fulfillment.uses_legacy_mode_shape() {
            continue;
        }
        if declared_toolchain_contract(toolchain_name, toolchain).is_none() {
            continue;
        }
        advisories.push(ContractAdvisory::LegacyFlatToolchainFulfillment(
            LegacyFlatToolchainFulfillmentAdvisory {
                toolchain_name: toolchain_name.clone(),
                mode: toolchain.fulfillment.mode(),
                location: format!("toolchains.{toolchain_name}.fulfillment"),
            },
        ));
    }
    advisories
}

fn collect_legacy_host_service_lifecycle_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for (service_name, service) in &contract.services {
        if service.manager.is_some() || service.provider.is_some() {
            continue;
        }
        let mut locations = Vec::new();
        if service.start.is_some() {
            locations.push(format!("services.{service_name}.start"));
        }
        if service.stop.is_some() {
            locations.push(format!("services.{service_name}.stop"));
        }
        if locations.is_empty() {
            continue;
        }
        advisories.push(ContractAdvisory::LegacyHostServiceLifecycle(
            LegacyHostServiceLifecycleAdvisory {
                service_name: service_name.clone(),
                locations,
            },
        ));
    }
    advisories
}

fn collect_legacy_service_readiness_run_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for (service_name, service) in &contract.services {
        let Some(readiness) = service.readiness.as_ref() else {
            continue;
        };
        if readiness
            .run
            .as_deref()
            .map(str::trim)
            .filter(|run| !run.is_empty())
            .is_none()
        {
            continue;
        }
        advisories.push(ContractAdvisory::LegacyServiceReadinessRun(
            LegacyServiceReadinessRunAdvisory {
                service_name: service_name.clone(),
                location: format!("services.{service_name}.readiness.run"),
            },
        ));
    }
    advisories
}

fn collect_service_uses_opaque_shell_start_advisories(
    contract: &Contract,
) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();

    for (task_name, task) in &contract.tasks {
        if task.launch.is_none()
            && task
                .runtime
                .as_ref()
                .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
        {
            let top_level_shell =
                opaque_shell_task_body(task.run.as_deref(), task.script.as_deref());
            if let Some((body_kind, body_location)) = top_level_shell {
                advisories.push(ContractAdvisory::ServiceUsesOpaqueShellStart(
                    ServiceUsesOpaqueShellStartAdvisory {
                        task_name: task_name.clone(),
                        body_kind: body_kind.to_string(),
                        body_location: format!("tasks.{task_name}.{body_location}"),
                        runtime_location: format!("tasks.{task_name}.runtime"),
                        launch_location: format!("tasks.{task_name}.launch"),
                    },
                ));
            }
        }

        let Some(execution) = task.execution.as_ref() else {
            continue;
        };

        for (backend, branch) in execution.modes.iter() {
            if branch.launch.is_some() {
                continue;
            }

            if !(branch.run.is_some()
                || branch.script.is_some()
                || branch.runtime.is_some()
                || task.run.is_some()
                || task.script.is_some())
            {
                continue;
            }

            let Some((body_kind, body_location)) = opaque_shell_branch_body(task, branch) else {
                continue;
            };

            let Some(runtime) = branch.runtime.as_ref().or(task.runtime.as_ref()) else {
                continue;
            };
            if runtime.kind != TaskRuntimeKind::Service {
                continue;
            }

            let backend_name = match backend {
                Backend::Native => "native",
                Backend::Container => "container",
                Backend::Remote => "remote",
            };
            advisories.push(ContractAdvisory::ServiceUsesOpaqueShellStart(
                ServiceUsesOpaqueShellStartAdvisory {
                    task_name: task_name.clone(),
                    body_kind: body_kind.to_string(),
                    body_location: match body_location {
                        OpaqueShellBodyLocation::Task(field) => {
                            format!("tasks.{task_name}.{field}")
                        }
                        OpaqueShellBodyLocation::Mode(field) => {
                            format!("tasks.{task_name}.execution.modes.{backend_name}.{field}")
                        }
                    },
                    runtime_location: if branch.runtime.is_some() {
                        format!("tasks.{task_name}.execution.modes.{backend_name}.runtime")
                    } else {
                        format!("tasks.{task_name}.runtime")
                    },
                    launch_location: format!(
                        "tasks.{task_name}.execution.modes.{backend_name}.launch"
                    ),
                },
            ));
        }
    }

    advisories
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OpaqueShellBodyLocation {
    Task(&'static str),
    Mode(&'static str),
}

fn opaque_shell_task_body<'a>(
    run: Option<&'a str>,
    script: Option<&'a str>,
) -> Option<(&'static str, &'static str)> {
    if has_non_empty_command(run) {
        Some(("run", "run"))
    } else if has_non_empty_command(script) {
        Some(("script", "script"))
    } else {
        None
    }
}

fn opaque_shell_branch_body(
    task: &TaskSpec,
    branch: &crate::schema::TaskModeBranchSpec,
) -> Option<(&'static str, OpaqueShellBodyLocation)> {
    if has_non_empty_command(branch.run.as_deref()) {
        Some(("run", OpaqueShellBodyLocation::Mode("run")))
    } else if has_non_empty_command(branch.script.as_deref()) {
        Some(("script", OpaqueShellBodyLocation::Mode("script")))
    } else if has_non_empty_command(task.run.as_deref()) {
        Some(("run", OpaqueShellBodyLocation::Task("run")))
    } else if has_non_empty_command(task.script.as_deref()) {
        Some(("script", OpaqueShellBodyLocation::Task("script")))
    } else {
        None
    }
}

fn collect_replaceable_shell_check_advisories(contract: &Contract) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for check in &contract.checks {
        if check.kind != CheckKind::Precondition {
            continue;
        }
        let Some(command) = check
            .run
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };

        if let Some(path) = obvious_file_check_path(command) {
            advisories.push(ContractAdvisory::ReplaceableShellCheck(
                ReplaceableShellCheckAdvisory {
                    check_name: check.name.clone(),
                    command: command.to_string(),
                    replacement_kind: ReplaceableShellCheckKind::File,
                    subject: path.to_string(),
                },
            ));
            continue;
        }

        if let Some(path) = obvious_env_check_path(command) {
            advisories.push(ContractAdvisory::ReplaceableShellCheck(
                ReplaceableShellCheckAdvisory {
                    check_name: check.name.clone(),
                    command: command.to_string(),
                    replacement_kind: ReplaceableShellCheckKind::Env,
                    subject: path.to_string(),
                },
            ));
        }
    }
    advisories
}

fn collect_replaceable_finite_shell_command_advisories(
    contract: &Contract,
) -> Vec<ContractAdvisory> {
    let mut advisories = Vec::new();
    for (task_name, task) in &contract.tasks {
        if task.aggregate.is_some()
            || task.prepare.is_some()
            || task.action.is_some()
            || task.command.is_some()
            || task.launch.is_some()
            || task
                .runtime
                .as_ref()
                .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
        {
            continue;
        }

        if let Some(advisory) = replaceable_finite_shell_command_advisory_for_task(
            task_name.as_str(),
            task.run.as_deref(),
            task.script.as_deref(),
            OpaqueShellBodyLocation::Task("run"),
            OpaqueShellBodyLocation::Task("script"),
        ) {
            advisories.push(ContractAdvisory::ReplaceableFiniteShellCommand(advisory));
            continue;
        }

        let Some(execution) = task.execution.as_ref() else {
            continue;
        };
        for (backend, branch) in execution.modes.iter() {
            if branch.command.is_some() || branch.launch.is_some() {
                continue;
            }
            if branch
                .runtime
                .as_ref()
                .or(task.runtime.as_ref())
                .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
            {
                continue;
            }
            let advisory = replaceable_finite_shell_command_advisory_for_task(
                task_name.as_str(),
                branch.run.as_deref().or(task.run.as_deref()),
                branch.script.as_deref().or(task.script.as_deref()),
                OpaqueShellBodyLocation::Mode("run"),
                OpaqueShellBodyLocation::Mode("script"),
            )
            .map(|mut advisory| {
                let backend_name = match backend {
                    Backend::Native => "native",
                    Backend::Container => "container",
                    Backend::Remote => "remote",
                };
                advisory.body_location = match advisory.body_location.as_str() {
                    "run" => format!("tasks.{task_name}.execution.modes.{backend_name}.run"),
                    "script" => {
                        format!("tasks.{task_name}.execution.modes.{backend_name}.script")
                    }
                    value => value.to_string(),
                };
                advisory
            });
            if let Some(advisory) = advisory {
                advisories.push(ContractAdvisory::ReplaceableFiniteShellCommand(advisory));
                break;
            }
        }
    }
    advisories
}

