    #[test]
    fn rejects_tcp_runtime_readiness_http_only_fields() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  dev:
    context: app
    run: echo hi
    runtime:
      kind: service
      readiness:
        kind: tcp
        listener: http
        method: HEAD
        headers:
          Accept: application/json
        success:
          status: [200]
        body:
          contains: "UP"
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              primary: true
              port:
                mode: fixed
                value: 3000
"#,
        )
        .unwrap();

        let errors = validate_contract(&contract).unwrap_err();
        assert!(errors.errors().iter().any(|error| {
            error
                .to_string()
                .contains("kind: tcp` must not declare `readiness.method`")
        }));
        assert!(errors.errors().iter().any(|error| {
            error
                .to_string()
                .contains("kind: tcp` must not declare `readiness.headers`")
        }));
        assert!(errors.errors().iter().any(|error| {
            error
                .to_string()
                .contains("kind: tcp` must not declare `readiness.success`")
        }));
        assert!(errors.errors().iter().any(|error| {
            error
                .to_string()
                .contains("kind: tcp` must not declare `readiness.body`")
        }));
    }

