    #[test]
    fn shared_local_backend_environment_intent_unifies_shape_validation() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/context:latest
  shared_backends:
    workbench:
      scope: local
      backend: container
      lifecycle: persistent
      environment:
        profile: java-node-workbench
tasks:
  dev:
    context: app
    run: echo dev
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
  dev:debug:
    context: app
    run: echo debug
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
"#,
        )
        .unwrap();

        let execution = contract.execution.as_ref().expect("execution should exist");
        let shared_backend = execution
            .shared_backends
            .get("workbench")
            .expect("shared backend should exist");
        let dev_shape = task_shared_container_backend_shape(
            &contract,
            execution,
            contract.tasks.get("dev").expect("dev should exist"),
            shared_backend,
        )
        .expect("dev shape should resolve");
        let debug_shape = task_shared_container_backend_shape(
            &contract,
            execution,
            contract
                .tasks
                .get("dev:debug")
                .expect("dev:debug should exist"),
            shared_backend,
        )
        .expect("debug shape should resolve");

        assert_eq!(dev_shape, debug_shape);
        assert_eq!(dev_shape.image, "profile:java-node-workbench");
    }

    #[test]
    fn empty_local_backend_environment_keeps_task_shape_image_fallback() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/app:latest
    debug:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/debug:latest
  shared_backends:
    workbench:
      scope: local
      backend: container
      lifecycle: persistent
      environment: {}
tasks:
  dev:
    context: app
    run: echo dev
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
  dev:debug:
    context: debug
    run: echo debug
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8081
"#,
        )
        .unwrap();

        let execution = contract.execution.as_ref().expect("execution should exist");
        let shared_backend = execution
            .shared_backends
            .get("workbench")
            .expect("shared backend should exist");
        let dev_shape = task_shared_container_backend_shape(
            &contract,
            execution,
            contract.tasks.get("dev").expect("dev should exist"),
            shared_backend,
        )
        .expect("dev shape should resolve");
        let debug_shape = task_shared_container_backend_shape(
            &contract,
            execution,
            contract
                .tasks
                .get("dev:debug")
                .expect("dev:debug should exist"),
            shared_backend,
        )
        .expect("debug shape should resolve");

        assert_eq!(dev_shape.image, "ghcr.io/ota/app:latest");
        assert_eq!(debug_shape.image, "ghcr.io/ota/debug:latest");
        assert_ne!(dev_shape.image, debug_shape.image);
    }

