    #[test]
    fn rejects_branch_tool_requirement_owned_by_toolchain_without_explicit_scope() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
tasks:
  lint:
    run: cargo fmt --check
    requirements:
      any_of:
        - when:
            backend: native
          tools:
            cargo: "*"
"#,
        )
        .unwrap();

        let rendered = validate_contract(&contract)
            .expect_err("branch tool requirements should demand explicit toolchain scope")
            .errors()
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>();

        assert!(
            rendered.iter().any(|error| error.contains(
                "task `lint` requirements.any_of[0] references tool requirement `cargo` in `requirements.tools` without an explicit toolchain scope"
            )),
            "{rendered:?}"
        );
    }

    #[test]
    fn rejects_non_normalized_agent_boundary_paths() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
tasks:
  test:
    run: cargo test
agent:
  writable_paths:
    - ../tmp
  protected_paths:
    - /etc/passwd
"#,
        )
        .unwrap();

        let rendered = validate_contract(&contract)
            .expect_err("agent boundary paths should be normalized")
            .errors()
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>();

        assert!(
            rendered.iter().any(|error| error.contains(
                "`agent.writable_paths` entries must be normalized relative paths without `..` or an absolute prefix",
            )),
            "{rendered:?}"
        );
        assert!(
            rendered.iter().any(|error| error.contains(
                "`agent.protected_paths` entries must be normalized relative paths without `..` or an absolute prefix",
            )),
            "{rendered:?}"
        );
    }

